contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;
        uint256 preBalance = address(c).balance;
        address preOwner = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 postBalance = address(c).balance;
        address postOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert((reverted && postBalance == preBalance || !reverted && postBalance == 0) && postOwner == preOwner);
    }

    receive() external payable {}
}

