// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address recipient, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.withdrawAll(recipient) {} catch { return; }
        uint256 preBalance = address(c).balance;
        address preOwner;
        try c.owner() returns (address __r) { preOwner = __r; } catch { return; }
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        uint256 postBalance = address(c).balance;
        address postOwner;
        try c.owner() returns (address __r) { postOwner = __r; } catch { return; }
        assertTrue((reverted && postBalance == preBalance || !reverted && postBalance == 0) && postOwner == preOwner);
    }

    function testFuzz_run(address recipient, uint256 amount) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(recipient, amount);
    }

    receive() external payable {}
}
